import assert from 'node:assert/strict';
import fs from 'node:fs';
import vm from 'node:vm';
import ts from 'typescript';
const module={exports:{}};
vm.runInNewContext(ts.transpileModule(fs.readFileSync('src/lib/jobPurchaseOrderAllocation.ts','utf8'),{compilerOptions:{module:ts.ModuleKind.CommonJS}}).outputText,{module,exports:module.exports});
const {allocateCommittedPOCosts}=module.exports;
const line={id:'line1',productId:'product1',quantity:4};
const po={id:'po1',salesOrderId:'sale1',projectId:'project1',productId:'product1',quantity:2,unitPrice:90,documentType:'po',status:'submitted'};
let result=allocateCommittedPOCosts('sale1','project1',[line],[po]);
assert.equal(result.allocations[0].orderedQuantity,2);
assert.equal(result.allocations[0].orderedUnitCost,90);
assert.equal(result.needsReview.length,0);
result=allocateCommittedPOCosts('sale1','project1',[line,{...line,id:'line2'}],[po]);
assert.equal(result.allocations[0].orderedQuantity,0);
assert.equal(result.needsReview.length,1);
result=allocateCommittedPOCosts('sale1','project1',[line],[{...po,quantity:5}]);
assert.equal(result.allocations[0].orderedQuantity,0);
assert.match(result.needsReview[0],/over-ordered/);
result=allocateCommittedPOCosts('sale1','project1',[line],[{...po,salesOrderId:'sale2'}]);
assert.equal(result.allocations[0].orderedQuantity,0);
assert.match(result.needsReview[0],/conflicting-job-link/);
result=allocateCommittedPOCosts('sale1','project1',[line],[{...po,status:'draft'}]);
assert.equal(result.allocations[0].orderedQuantity,0);
result=allocateCommittedPOCosts('sale1','project1',[line],[{...po,documentType:'rfq'}]);
assert.equal(result.allocations[0].orderedQuantity,0);
console.log('Job purchasing allocation tests passed');
